const $=s=>document.querySelector(s);let ctx;const audio=async()=>{ctx??=new(window.AudioContext||window.webkitAudioContext)();await ctx.resume();return ctx};const read=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}};const save=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch{}};
$('#date').textContent=new Date().toLocaleDateString('es-CL',{weekday:'long',day:'numeric',month:'long'});
let bpm=read('cuerda-bpm',90),playing=false,next=0,step=0,scheduler,visuals=[],activeOsc=new Set();
function tone(freq,time,duration=.05,vol=.2,type='sine'){let o=ctx.createOscillator(),g=ctx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(0,time);g.gain.linearRampToValueAtTime(vol,time+.005);g.gain.exponentialRampToValueAtTime(.001,time+duration);o.connect(g);g.connect(ctx.destination);o.start(time);o.stop(time+duration+.02);activeOsc.add(o);o.onended=()=>{activeOsc.delete(o);o.disconnect();g.disconnect()}}
function setBpm(v){bpm=Math.max(30,Math.min(240,Math.round(Number(v)||90)));$('#bpm').value=bpm;$('#tempoRange').value=bpm;$('#tempoName').textContent=bpm<76?'Adagio · con calma':bpm<108?'Andante · a tu paso':bpm<140?'Moderato · en movimiento':'Allegro · con energía';save('cuerda-bpm',bpm)}setBpm(bpm);
function beats(){ $('#beats').innerHTML=Array.from({length:+$('#meter').value},()=>'<span class="beat"></span>').join('');step=0 }beats();
function schedule(){while(next<ctx.currentTime+.1){let sub=+$('#sub').value,meter=+$('#meter').value,index=step%(meter*sub),beat=Math.floor(index/sub);tone(index===0?1200:index%sub===0?850:550,next,.035,+$('#volume').value/100*.4,index%sub?'sine':'triangle');if(index%sub===0){let id=setTimeout(()=>{if(!playing)return;document.querySelectorAll('.beat').forEach((el,i)=>el.classList.toggle('on',i===beat))},Math.max(0,(next-ctx.currentTime)*1000));visuals.push(id);if(visuals.length>100)visuals.shift()}next+=60/bpm/sub;step++}}
function stopMetro(){playing=false;clearInterval(scheduler);visuals.forEach(clearTimeout);visuals=[];activeOsc.forEach(o=>{try{o.stop()}catch{}});$('#play').textContent='▶  Iniciar metrónomo';$('#metroStatus').textContent='EN PAUSA';document.querySelectorAll('.beat').forEach(e=>e.classList.remove('on'))}
$('#play').onclick=async()=>{if(playing){stopMetro();return}try{await audio();playing=true;step=0;next=ctx.currentTime+.04;schedule();scheduler=setInterval(schedule,25);$('#play').textContent='Ⅱ  Pausar metrónomo';$('#metroStatus').textContent='SONANDO'}catch{$('#metroStatus').textContent='AUDIO NO DISPONIBLE'}};
$('#bpm').onchange=e=>setBpm(e.target.value);$('#tempoRange').oninput=e=>setBpm(e.target.value);$('#minus').onclick=()=>setBpm(bpm-1);$('#plus').onclick=()=>setBpm(bpm+1);$('#meter').onchange=beats;$('#sub').onchange=()=>step=0;let taps=[];$('#tap').onclick=()=>{const t=performance.now();if(t-(taps.at(-1)||0)>2000)taps=[];taps.push(t);taps=taps.slice(-6);if(taps.length>1)setBpm(60000/((t-taps[0])/(taps.length-1)))};document.addEventListener('keydown',e=>{if(e.code==='Space'&&!/INPUT|TEXTAREA|SELECT|BUTTON/.test(e.target.tagName)){e.preventDefault();$('#play').click()}});
const tuning=[['E',40],['A',45],['D',50],['G',55],['B',59],['E',64]];tuning.forEach(([n,m],i)=>{const b=document.createElement('button');b.innerHTML=n+'<small>'+(6-i)+'ª</small>';b.title='Escuchar '+n+Math.floor(m/12-1);b.onclick=async()=>{try{await audio();tone(+$('#a4').value*2**((m-69)/12),ctx.currentTime,.95,.18,'triangle')}catch{$('#tuneMessage').textContent='Audio no disponible en este navegador.'}};$('#strings').append(b)});
let stream,analyser,source,frame,micOn=false,lastNote=0;const names=['C','C♯','D','D♯','E','F','F♯','G','G♯','A','A♯','B'];
function detectPitch(buf,sampleRate){let rms=0;for(let v of buf)rms+=v*v;if(Math.sqrt(rms/buf.length)<.008)return null;const min=Math.floor(sampleRate/1100),max=Math.floor(sampleRate/65),n=buf.length-max;let dif=new Float32Array(max+1),sum=0;for(let tau=1;tau<=max;tau++){let v=0;for(let i=0;i<n;i++){const d=buf[i]-buf[i+tau];v+=d*d}dif[tau]=v;sum+=v;dif[tau]=sum?v*tau/sum:1}for(let tau=min;tau<max-1;tau++){if(dif[tau]<.13){while(tau+1<max&&dif[tau+1]<dif[tau])tau++;let a=dif[tau-1],b=dif[tau],c=dif[tau+1],den=a-2*b+c;let better=tau+(den?(a-c)/(2*den):0);return sampleRate/better}}return null}
const buffer=new Float32Array(4096);let lastFrame=0;
function listen(t){if(!micOn)return;frame=requestAnimationFrame(listen);if(t-lastFrame<90)return;lastFrame=t;analyser.getFloatTimeDomainData(buffer);let f=detectPitch(buffer,ctx.sampleRate);if(!f){if(t-lastNote>1500){$('#note').textContent='—';$('#frequency').textContent='Escuchando…';$('#tuneMessage').textContent='Toca una cuerda a la vez.';$('#needle').style.left='50%';$('#cents').textContent='— cents'}return}lastNote=t;let midi=69+12*Math.log2(f/Number($('#a4').value)),rounded=Math.round(midi),cents=Math.round((midi-rounded)*100);$('#note').textContent=names[(rounded%12+12)%12];$('#frequency').textContent=f.toFixed(1)+' Hz · octava '+(Math.floor(rounded/12)-1);$('#cents').textContent=(cents>0?'+':'')+cents+' cents';$('#needle').style.left=(50+cents*.9)+'%';$('#tuneMessage').textContent=Math.abs(cents)<=5?'✓ Afinada':cents<0?'Está grave · tensa suavemente la cuerda':'Está aguda · afloja suavemente la cuerda'}
function stopMic(){micOn=false;cancelAnimationFrame(frame);stream?.getTracks().forEach(t=>t.stop());source?.disconnect();analyser?.disconnect();$('#mic').textContent='♬  Activar micrófono';$('#frequency').textContent='Micrófono apagado';$('#note').textContent='—'}
$('#mic').onclick=async()=>{if(micOn){stopMic();return}$('#mic').disabled=true;$('#mic').textContent='Solicitando permiso…';try{if(!navigator.mediaDevices?.getUserMedia)throw Error('unsupported');await audio();stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:false,noiseSuppression:false,autoGainControl:false}});if(playing)stopMetro();analyser=ctx.createAnalyser();analyser.fftSize=4096;source=ctx.createMediaStreamSource(stream);source.connect(analyser);micOn=true;$('#mic').textContent='■  Apagar micrófono';$('#tuneMessage').textContent='Escuchando tu guitarra…';frame=requestAnimationFrame(listen)}catch(e){$('#mic').textContent='♬  Activar micrófono';$('#tuneMessage').textContent=e.name==='NotAllowedError'?'Permite el micrófono en tu navegador y vuelve a intentar.':e.name==='NotFoundError'?'No se encontró un micrófono. Conecta uno e intenta de nuevo.':'No se pudo activar el micrófono. Usa un navegador compatible con HTTPS.'}finally{$('#mic').disabled=false}};
const chords=[['C','major',[-1,3,2,0,1,0]],['D','major',[-1,-1,0,2,3,2]],['E','major',[0,2,2,1,0,0]],['G','major',[3,2,0,0,0,3]],['A','major',[-1,0,2,2,2,0]],['Am','minor',[-1,0,2,2,1,0]],['Em','minor',[0,2,2,0,0,0]],['Dm','minor',[-1,-1,0,2,3,1]],['A7','seventh',[-1,0,2,0,2,0]],['E7','seventh',[0,2,0,1,0,0]],['D7','seventh',[-1,-1,0,2,1,2]]];
function drawChords(){let chosen=chords.filter(c=>$('#chordFilter').value==='all'||c[1]===$('#chordFilter').value);$('#chordList').innerHTML=chosen.map(([name,type,frets])=>{let svg='';for(let s=0;s<6;s++)svg+=`<line x1="${17+s*12}" x2="${17+s*12}" y1="25" y2="105" stroke="#bcc8b3"/>`;for(let f=0;f<5;f++)svg+=`<line x1="17" x2="77" y1="${25+f*20}" y2="${25+f*20}" stroke="#9cac90" stroke-width="${f===0?3:1}"/>`;frets.forEach((f,s)=>{svg+=f>0?`<circle cx="${17+s*12}" cy="${15+f*20}" r="5" fill="#5e7d4b"/>`:`<text x="${17+s*12}" y="15" text-anchor="middle" font-size="11" fill="#8c9d7e">${f<0?'×':'○'}</text>`});return `<div class="chord"><strong>${name}</strong><svg role="img" aria-label="Acorde ${name}, cuerdas de sexta a primera: ${frets.map(x=>x<0?'no tocar':x===0?'al aire':'traste '+x).join(', ')}" viewBox="0 0 95 115">${svg}</svg></div>`}).join('')}drawChords();$('#chordFilter').onchange=drawChords;
let duration=900,remaining=duration,timerOn=false,deadline=0,timerInterval;function renderTime(){$('#timer').textContent=Math.floor(remaining/60).toString().padStart(2,'0')+':'+(remaining%60).toString().padStart(2,'0')}function pauseTimer(){timerOn=false;clearInterval(timerInterval);$('#timerPlay').textContent='Continuar sesión'}function tick(){remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000));renderTime();if(!remaining){pauseTimer();$('#timerPlay').textContent='Nueva sesión';$('#sessionStatus').textContent='✓ Sesión completada. ¡Buen trabajo!';if(ctx?.state==='running'){tone(660,ctx.currentTime,.3,.12);tone(880,ctx.currentTime+.35,.5,.12)}}}$('#timerPlay').onclick=async()=>{if(timerOn){tick();pauseTimer();return}try{await audio()}catch{}if(!remaining)remaining=duration;deadline=Date.now()+remaining*1000;timerOn=true;$('#timerPlay').textContent='Pausar sesión';$('#sessionStatus').textContent='Concéntrate en tocar. El tiempo corre.';timerInterval=setInterval(tick,200)};$('#timerReset').onclick=()=>{pauseTimer();remaining=duration;renderTime();$('#timerPlay').textContent='Iniciar sesión';$('#sessionStatus').textContent='Un espacio para avanzar, sin prisa.'};document.querySelectorAll('[data-min]').forEach(b=>b.onclick=()=>{duration=Number(b.dataset.min)*60;$('#timerReset').click();document.querySelectorAll('[data-min]').forEach(x=>x.classList.toggle('selected',x===b))});$('#notes').value=read('cuerda-notes','');$('#notes').oninput=()=>save('cuerda-notes',$('#notes').value);const day=new Date().toLocaleDateString('en-CA'),tasks=read('cuerda-tasks-'+day,[]);document.querySelectorAll('[data-task]').forEach(c=>{c.checked=tasks.includes(c.dataset.task);c.onchange=()=>save('cuerda-tasks-'+day,[...document.querySelectorAll('[data-task]:checked')].map(e=>e.dataset.task))});document.addEventListener('visibilitychange',()=>{if(document.hidden){if(playing)stopMetro();if(micOn)stopMic()}else if(timerOn)tick()});
